<script lang="ts">
 import { busyKeys, runBusy } from "./busy"; import { toast } from "./toast";
 export let initialLate:number|null=null; export let initialReturn:number|null=null; export let language='en'; export let onApply:(values:{lateAfterMinutesOverride:number|null;returnWindowMinutesOverride:number|null})=>Promise<boolean|void>|boolean|void=()=>{};
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 let lateText='', returnText='', error='';
 $: if (lateText===''&&initialLate!==null) lateText=String(initialLate);
 $: if (returnText===''&&initialReturn!==null) returnText=String(initialReturn);
 function reset(){lateText=initialLate===null?'':String(initialLate);returnText=initialReturn===null?'':String(initialReturn);error=''}
 async function apply(){let late:number|null=null;if(String(lateText).trim()){const time=String(lateText).match(/^(-)?(\d{1,3}):([0-5]\d)$/);if(time){late=(Number(time[2])*60+Number(time[3]))*(time[1]?-1:1)}else if(!/^-?\d+$/.test(String(lateText))){error=t('迟到时间格式应为 HH:mm 或分钟','Use HH:mm or minutes for the late override');return}else late=Number(lateText);if(late < -60||late>120){error=t('迟到阈值范围为 −60 至 120 分钟','Late override must be between −60 and 120 minutes');return}}let ret:number|null=null;if(String(returnText).trim()){if(!/^\d+$/.test(String(returnText))||Number(returnText)<1||Number(returnText)>60){error=t('返回窗口范围为 1 至 60 分钟','Return window must be between 1 and 60 minutes');return}ret=Number(returnText)}error='';await runBusy('live-overrides',async()=>{try{const saved=await onApply({lateAfterMinutesOverride:late,returnWindowMinutesOverride:ret});if(saved===false)toast.error(t('保存失败：','Save failed:'));else toast.success(t('设置已应用','Settings applied'))}catch(reason){toast.error(`${t('保存失败：','Save failed:')}${reason instanceof Error?reason.message:String(reason)}`)}})}
</script>
<div class="override-form"><label>{t('迟到覆盖（HH:mm 或分钟，−60 至 120）','Late override (HH:mm or minutes, −60 to 120)')}<input bind:value={lateText} placeholder={t('10 或 00:10','10 or 00:10')}/></label><label>{t('返回窗口覆盖（1 至 60 分钟）','Return override (1 to 60 minutes)')}<input type="number" min="1" max="60" bind:value={returnText}/></label><div class="form-actions"><button disabled={$busyKeys.has('live-overrides')} onclick={reset}>{t('重置','Reset')}</button><button class="primary" disabled={$busyKeys.has('live-overrides')} onclick={apply}>{$busyKeys.has('live-overrides') ? t('保存中…','Saving…') : t('应用设置','Apply')}</button></div>{#if error}<span class="error">{error}</span>{/if}</div>
<style>.override-form{display:grid;grid-template-columns:1fr 1fr;align-items:end;gap:10px}.override-form label{display:grid;gap:5px;font-size:11px;color:var(--muted);min-width:0}.override-form input{width:100%;min-width:0;box-sizing:border-box;padding:7px;border:1px solid var(--line-strong);border-radius:6px}.form-actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:8px}.error{color:var(--danger);font-size:12px;grid-column:1/-1}@media(max-width:520px){.override-form{grid-template-columns:1fr}}</style>
